const buscador=document.getElementById("busqueda"),peliculas=document.querySelectorAll(".pelicula"),mensaje=document.getElementById("sin-resultados");let peliculasVistas=JSON.parse(localStorage.getItem("peliculasVistas")||"[]");peliculas.forEach(function(e){let t=e.querySelector(".boton-vista"),s=e.dataset.id;function i(){let i=peliculasVistas.includes(s);e.classList.toggle("vista",i),t.textContent=i?"✓ Vista":"Marcar como vista",t.setAttribute("aria-pressed",String(i))}i(),t.addEventListener("click",function(){peliculasVistas.includes(s)?peliculasVistas=peliculasVistas.filter(function(e){return e!==s}):peliculasVistas.push(s),localStorage.setItem("peliculasVistas",JSON.stringify(peliculasVistas)),i()})}),buscador.addEventListener("input",function(){let e=buscador.value.toLowerCase().trim(),t=0;peliculas.forEach(function(s){let i=s.querySelector("h2").textContent.toLowerCase();i.includes(e)?(s.hidden=!1,t++):s.hidden=!0}),mensaje.hidden=t>0});